fn is_integer(text: &Vec<char>) -> bool {
    // An empty array is considered to consist entirely of decimal digits
    if text.is_empty() {
        return true;
    }

    // Check each character in the vector
    for &c in text {
        // Check if the character is not a digit
        if !c.is_digit(10) {
            return false; // Return false if any character is not a digit
        }
    }

    // All characters are digits
    true
}